#!/usr/bin/env bash
# Writes codegen/client.tmpl and codegen/imports.tmpl from the templates of the
# oapi-codegen version pinned in generate.go. `go generate` runs this before
# oapi-codegen, so the overrides always follow the pinned release.
#
# Why override at all: package sinatra holds both the generated code and the
# hand-written client, so the generator must not emit its own exported
# NewClient, Client, ClientOption or WithHTTPClient. The overrides keep only
#   client.tmpl   the request builders, unexported (newTasksGetRequest, ...)
#   imports.tmpl  the "Code generated ... DO NOT EDIT." header, without the
#                 generator's package comment (sinatra.go has the real one)
# and codegen/client-with-responses.tmpl (hand-written, not derived) drops the
# typed-response client.
#
# Fails if a template no longer has the shape this expects, rather than
# writing a wrong override.
set -euo pipefail
cd "$(dirname "$0")/.."

version=$(sed -n 's|^//go:generate go run github.com/oapi-codegen/oapi-codegen/v2/cmd/oapi-codegen@\(v[0-9.]*\) .*|\1|p' generate.go)
[ -n "$version" ] || { echo "derive-templates: no pinned oapi-codegen version in generate.go" >&2; exit 1; }

dir=$(go mod download -json "github.com/oapi-codegen/oapi-codegen/v2@$version" | sed -n 's/^[[:space:]]*"Dir": "\(.*\)",$/\1/p')
src="$dir/pkg/codegen/templates"
[ -f "$src/client.tmpl" ] && [ -f "$src/imports.tmpl" ] ||
  { echo "derive-templates: no templates in $src" >&2; exit 1; }

header() {
  printf '{{- /* Derived from oapi-codegen %s pkg/codegen/templates/%s by scripts/derive-templates.sh. Do not edit. */ -}}\n' "$version" "$1"
}

# client.tmpl: from the request builders' marker up to applyEditors, with the
# builders unexported.
start='{{/* Generate request builders */}}'
# shellcheck disable=SC2016 # template text, not shell
stop='func (c *{{ $clientTypeName }}) applyEditors'
[ "$(grep -cF "$start" "$src/client.tmpl")" = 1 ] && [ "$(grep -cF "$stop" "$src/client.tmpl")" = 1 ] ||
  { echo "derive-templates: client.tmpl changed shape (markers not found once each)" >&2; exit 1; }
{
  header client.tmpl
  awk -v start="$start" -v stop="$stop" '
    index($0, start) == 1 { on = 1 }
    index($0, stop) == 1 { on = 0 }
    on { gsub(/New\{\{\$opid\}\}Request/, "new{{$opid}}Request"); print }
  ' "$src/client.tmpl"
} >codegen/client.tmpl
# shellcheck disable=SC2016 # template text, not shell
if grep -qF -e 'New{{$opid}}' -e NewClient -e ClientOption codegen/client.tmpl; then
  echo "derive-templates: codegen/client.tmpl still exports a constructor" >&2
  exit 1
fi

# imports.tmpl: drop the two-line package comment and leave a blank line
# between the generated-code header and the package clause, so the header
# isn't read as package documentation.
pkg='// Package {{.PackageName}} provides primitives to interact with the openapi HTTP API.'
gen='// Code generated by {{.ModuleName}} version {{.Version}} DO NOT EDIT.'
[ "$(grep -cxF "$pkg" "$src/imports.tmpl")" = 1 ] && [ "$(grep -cxF "$gen" "$src/imports.tmpl")" = 1 ] ||
  { echo "derive-templates: imports.tmpl changed shape (header lines not found once each)" >&2; exit 1; }
{
  header imports.tmpl
  awk -v pkg="$pkg" -v gen="$gen" '
    $0 == pkg { skip = 1; next }
    skip && $0 == "//" { skip = 0; next }
    { skip = 0 }
    $0 == gen { print; print ""; next }
    { print }
  ' "$src/imports.tmpl"
} >codegen/imports.tmpl
